/* RESTORE_RECORD:articles */ {"id": 246, "url": "https://www.youtube.com/watch?v=S_zLSKDRYT0", "original_source_url": "https://www.youtube.com/watch?v=S_zLSKDRYT0", "source": "YouTube: Al Jazeera English", "source_status": "ACTIVE", "source_removed_notice": null, "source_last_checked_at": null, "creation_origin": "AI_SYNTHESIZED", "position_placement": "STANDARD", "display_order": 0, "is_pinned": false, "title": "How Israel's UNRWA ban is affecting education and healthcare in Gaza", "author": "Al Jazeera English", "published_at": "2026-09-24T06:55:45", "category": "international", "content_text": "UNRWA has long provided education, healthcare and aid to Palestinians in Gaza, but Israeli restrictions have left much of its network non-functional. Before the war, 300,000 children attended 288 UNRWA-run schools; many now shelter displaced families instead. Of 22 healthcare centres once operating across the Strip, only six remain active, leaving patients with chronic illnesses struggling to access medicine. The agency says it can no longer bring in aid independently, relying instead on international partners for supplies.\n\nAl Jazeera's Tareq Abu Azzoum reports from Khan Younis, Gaza.\n\nSubscribe to our channel: \nFollow us on X: \nFind us on Facebook: \nCheck our website: \nCheck out our Instagram page: \nDownload AJE Mobile App: \n\n#Palestine #UNRWA #Gaza #GazaHumanitarianCrisis #GazaEducationCrisis #GazaHealthcareCrisis #PalestinianRefugees #Israel #UNRWABan #GazaWar", "summary": "How Israel's UNRWA ban is affecting education and healthcare in Gaza", "extracted_entities": {"platform": "youtube", "video_id": "S_zLSKDRYT0", "channel_id": "UCNye-wNBqNL5ZzHSJj3l8Bg", "is_video_news": true}, "scrape_status": "completed", "missing_fields": [], "retry_count": 0, "is_featured": false, "is_breaking": false, "views_count": 0, "likes_count": 0, "shares_count": 0, "scheduled_at": null, "block_number": 244, "block_hash": "fa4f7f9d92426149d778fc442605b2227bc63026f104d27b8ffdd09