/* RESTORE_RECORD:articles */ {"id": 398, "url": "https://bangla.thedailystar.net/node/3895451", "original_source_url": "https://bangla.thedailystar.net/node/3895451", "source": "daily_star_bangla", "source_status": "ACTIVE", "source_removed_notice": null, "source_last_checked_at": null, "creation_origin": "AI_SYNTHESIZED", "position_placement": "STANDARD", "display_order": 0, "is_pinned": false, "title": "Apps", "author": "The Daily Star", "published_at": null, "category": "politics", "content_text": "Get the latest, breaking, opinion, politics, lifestyle, entertainment, crime news from the newspaper and online edition at your smartphone. For mobile, for tablet, for free. This app brings you breaking news and full access to The Daily Star's content.\n\nFor mobile, for tablet, for free. This app brings you breaking news and full access to the The Daily Star newspaper and online edition's content.", "summary": null, "extracted_entities": {}, "scrape_status": "partial", "missing_fields": ["published_at"], "retry_count": 0, "is_featured": false, "is_breaking": false, "views_count": 0, "likes_count": 0, "shares_count": 0, "scheduled_at": null, "block_number": 393, "block_hash": "65b574cee7265b4fbd8621adc2e187aea1278021bbfb609684f601ad3b13ac1f", "prev_hash": "00d12e01a3d526385e32570b2a7ceb314101ca0c50a0f2eb6c0ca2569f3b6f99", "digital_signature": "703c5996946e0b19ddd0fdc0c87c215d4267420c344e1c3a936c2b497d25d099", "is_ledger_verified": true, "images": [], "lead_image_url": "/static/img/placeholders/politics.svg", "created_at": "2026-09-24T07:30:43"}
